// 8x16 ASCII字库(部分)
const uint8_t F8X16[][16] = {
    {0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,  // ' '
     0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00},
    {0x00,0x00,0x3C,0x42,0x42,0x42,0x3C,0x00,  // '0'
     0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00},
    // ...更多字符
};

// 显示1个字符
void oledShowChar(uint8_t x, uint8_t y, char ch) {
    if (ch < 32 || ch > 127) ch = ' ';
    uint8_t c = ch - 32;
    // 设置位置
    oledSetPos(x, y);
    // 写上半8字节
    for (int i = 0; i < 8; i++)
        oledWriteData(F8X16[c][i]);
    // 设置下一页
    oledSetPos(x, y + 1);
    // 写下半8字节
    for (int i = 0; i < 8; i++)
        oledWriteData(F8X16[c][i + 8]);
}

// 显示字符串
void oledShowString(uint8_t x, uint8_t y, char* str) {
    while (*str) {
        oledShowChar(x, y, *str);
        x += 8;
        str++;
    }
}

// OLED显存缓冲区
uint8_t oledGRAM[8][128];  // 8页128列

// 画点
void oledDrawPoint(uint8_t x, uint8_t y, uint8_t color) {
    if (x >= 128 || y >= 64) return;
    uint8_t page = y / 8;
    uint8_t bit = y % 8;
    if (color)
        oledGRAM[page][x] |= (1 << bit);   // 画点
    else
        oledGRAM[page][x] &= ~(1 << bit);  // 擦点
}

// 刷新显存到OLED
void oledRefresh(void) {
    for (uint8_t i = 0; i < 8; i++) {
        oledSetPos(0, i);
        for (uint8_t j = 0; j < 128; j++)
            oledWriteData(oledGRAM[i][j]);
    }
}

// 画线(Bresenham算法)
void oledDrawLine(uint8_t x1, uint8_t y1, uint8_t x2, uint8_t y2) {
    int dx = x2 - x1, dy = y2 - y1;
    int steps = abs(dx) > abs(dy) ? abs(dx) : abs(dy);
    float xInc = (float)dx / steps;
    float yInc = (float)dy / steps;
    float x = x1, y = y1;
    for (int i = 0; i <= steps; i++) {
        oledDrawPoint((uint8_t)x, (uint8_t)y, 1);
        x += xInc;
        y += yInc;
    }
}

// 显示图片(128x64)
void oledShowImage(uint8_t x, uint8_t y, const uint8_t* img, 
                  uint8_t w, uint8_t h) {
    for (uint8_t i = 0; i < (h+7)/8; i++) {
        for (uint8_t j = 0; j < w; j++) {
            oledGRAM[y/8 + i][x + j] = img[i*w + j];
        }
    }
    oledRefresh();
}

// DHT11读取(简化)
#define DHT_PIN  GPIO_PIN_0
#define DHT_PORT GPIOA

uint8_t dht11Read(uint8_t* temp, uint8_t* humi) {
    uint8_t data[5] = {0};
    // 启动信号
    HAL_GPIO_WritePin(DHT_PORT, DHT_PIN, GPIO_PIN_RESET);
    HAL_Delay(20);  // 拉低20ms
    HAL_GPIO_WritePin(DHT_PORT, DHT_PIN, GPIO_PIN_SET);
    // 等待响应和读取(时序略)
    // ...
    // 校验
    if (data[4] == (data[0]+data[1]+data[2]+data[3])) {
        *humi = data[0];
        *temp = data[2];
        return 0;  // 成功
    }
    return 1;  // 失败
}

