// OLED显示温湿度
void displayTempHumi(uint8_t temp, uint8_t humi) {
    char buf[20];

    oledClear();
    oledShowString(0, 0, "Weather Station");
    oledShowString(0, 2, "Temp:");
    sprintf(buf, "%d C", temp);
    oledShowString(48, 2, buf);

    oledShowString(0, 4, "Humi:");
    sprintf(buf, "%d %%", humi);
    oledShowString(48, 4, buf);

    oledRefresh();
}

// 主循环
while (1) {
    uint8_t temp, humi;
    if (dht11Read(&temp, &humi) == 0) {
        displayTempHumi(temp, humi);
        printf("T:%d H:%d\r\n", temp, humi);
    }
    HAL_Delay(2000);  // 2秒更新
}

// 显示浮点数据
void showFloatData(uint8_t x, uint8_t y, char* label, float val, char* unit) {
    char buf[20];
    oledShowString(x, y, label);
    sprintf(buf, "%.1f%s", val, unit);
    oledShowString(x + 40, y, buf);
}

// 使用
showFloatData(0, 2, "T:", 25.6f, "C");
showFloatData(0, 4, "H:", 60.5f, "%");
showFloatData(0, 6, "L:", 850.0f, "lx");

